type track struct {
	ID, Name, Team, Topic, Theory, Practice, Risk string
	Questions                                     []Question
}

func q(id, prompt string, options []string, correct int, why string) Question {
	return Question{ID: id, Prompt: prompt, Options: options, Correct: correct, Explanation: why}
}
