	s := Settings{TelegramUsername: getenv("TELEGRAM_BOT_USERNAME", ""), TelegramEnabled: getenv("TELEGRAM_ENABLED", "false") == "true", RouterAIBaseURL: getenv("ROUTERAI_BASE_URL", "https://routerai.ru/api/v1"), RouterAIModel: getenv("ROUTERAI_MODEL", ""), AIMockMode: getenv("AI_MOCK_MODE", "true") == "true", AppURL: a.appURL, AITimeoutSeconds: envint("AI_REQUEST_TIMEOUT_SECONDS", 60), AIMaxTokens: envint("AI_MAX_TOKENS", 1500)}
	token, key := getenv("TELEGRAM_BOT_TOKEN", ""), getenv("ROUTERAI_API_KEY", "")
